import { TeamMatchRecord } from "@/types";
import { importedHistories } from "@/data/imported-data";

/**
 * Historial real de partidos, cargado a mano por equipo a partir de una
 * investigación en internet. Para Ararat-Armenia y Celje, resultados,
 * córners, remates y tiros al arco de los cuatro partidos de julio/agosto
 * proceden de RedScores. El 5-0 Celje-Aluminij y sus córners se contrastaron
 * con la PrvaLiga y TotalCorner; solo sus remates y la posesión de todos los
 * registros son estimaciones porque esas fuentes no publican ese campo.
 *
 * Levski y Kairat proceden principalmente de las fichas de partido de
 * FotMob; Atyrau-Kairat se contrastó con TotalCorner. Se eligieron cinco
 * encuentros con estadísticas completas por club. Los datos del
 * Kairat-Omonia del 29/07 incluyen prórroga y deben interpretarse como 120
 * minutos, no como una producción equivalente a 90 minutos.
 *
 * Para agregar un equipo nuevo: buscar sus últimos partidos reales y
 * añadir una entrada en este mapa con el mismo shape.
 */
