function combineRecord(builtIn: TeamMatchRecord, imported: TeamMatchRecord): TeamMatchRecord {
  return {
    ...builtIn,
    ...imported,
    goalsForFirstHalf: imported.goalsForFirstHalf ?? builtIn.goalsForFirstHalf,
    goalsAgainstFirstHalf: imported.goalsAgainstFirstHalf ?? builtIn.goalsAgainstFirstHalf,
    goalsForSecondHalf: imported.goalsForSecondHalf ?? builtIn.goalsForSecondHalf,
    goalsAgainstSecondHalf: imported.goalsAgainstSecondHalf ?? builtIn.goalsAgainstSecondHalf,
    shotsOnTargetFor: imported.shotsOnTargetFor ?? builtIn.shotsOnTargetFor,
    shotsOnTargetAgainst: imported.shotsOnTargetAgainst ?? builtIn.shotsOnTargetAgainst,
    possession: imported.possession ?? builtIn.possession,
  };
}

const ensureSecondHalfGoals = (record: TeamMatchRecord): TeamMatchRecord => {
  const h2For =
    record.goalsForSecondHalf !== undefined
      ? record.goalsForSecondHalf
      : record.goalsForFirstHalf !== undefined
      ? record.goalsFor - record.goalsForFirstHalf
      : undefined;

  const h2Against =
    record.goalsAgainstSecondHalf !== undefined
      ? record.goalsAgainstSecondHalf
      : record.goalsAgainstFirstHalf !== undefined
      ? record.goalsAgainst - record.goalsAgainstFirstHalf
      : undefined;

  return {
    ...record,
    goalsForSecondHalf: h2For,
    goalsAgainstSecondHalf: h2Against,
  };
};

function combineHistories(
  builtInMap: Record<string, TeamMatchRecord[]>,
  importedMap: Record<string, TeamMatchRecord[]>
): Record<string, TeamMatchRecord[]> {
  const allKeys = new Set([...Object.keys(builtInMap), ...Object.keys(importedMap)]);
  const result: Record<string, TeamMatchRecord[]> = {};

  for (const key of allKeys) {
    const builtInList = builtInMap[key] ?? [];
    const importedList = importedMap[key] ?? [];

    let list: TeamMatchRecord[] = [];

    // Si existen 15 partidos oficiales transcritos/importados para este equipo (en imported-analysis-packages.json),
    // usarlos con prioridad absoluta sobre los datos built-in estáticos.
    if (importedList.length >= 15) {
      list = [...importedList];
    } else if (builtInList.length >= 15 && importedList.length === 0) {
      list = [...builtInList];
    } else {
      const map = new Map<string, TeamMatchRecord>();
      builtInList.forEach((r) => map.set(r.date || r.matchId, r));
      importedList.forEach((r) => {
        const key = r.date || r.matchId;
        const existing = map.get(key);
        if (existing) {
          map.set(key, combineRecord(existing, r));
        } else {
          map.set(key, r);
        }
      });
      list = [...map.values()].sort((a, b) => b.date.localeCompare(a.date));
    }

    result[key] = list.map(ensureSecondHalfGoals);
  }

  return result;
}

export const allTeamHistories: Record<string, TeamMatchRecord[]> = combineHistories(
  BUILT_IN_HISTORIES,
  importedHistories
);

export function getTeamMatchPool(teamId: string): TeamMatchRecord[] {
  return allTeamHistories[teamId] ?? [];
}

export function getTeamMatchHistory(teamId: string, count: number): TeamMatchRecord[] {
  return getTeamMatchPool(teamId).slice(0, count);
}
